import { UMAMI_SHARE_ID, UMAMI_SHARE_URL } from "../config/umami";

/**
 * Stats are baked into a same-origin JSON file (public/umami-stats.json)
 * so browsers with ad blockers never need to contact umami.is.
 */
export function getShareUrl() {
  return UMAMI_SHARE_URL;
}

export function getShareId() {
  return UMAMI_SHARE_ID;
}

export function getStatsJsonUrl() {
  const base = (process.env.PUBLIC_URL || "").replace(/\/$/, "");
  return `${base}/umami-stats.json`;
}

export async function fetchAllStats() {
  const url = getStatsJsonUrl();
  const res = await fetch(url, {
    headers: { Accept: "application/json" },
    cache: "no-cache",
  });
  if (!res.ok) throw new Error(`stats_json_${res.status}`);
  const data = await res.json();
  if (!data?.summary) throw new Error("stats_json_invalid");
  return {
    summary: data.summary,
    active: data.active || { visitors: 0 },
    countries: Array.isArray(data.countries) ? data.countries : [],
    pages: Array.isArray(data.pages) ? data.pages : [],
    generatedAt: data.generatedAt || null,
  };
}
