import { useEffect, useState } from "react";
import { fetchAllStats } from "../lib/umamiApi";

export function useUmamiStats() {
  const [state, setState] = useState({
    loading: true,
    error: null,
    summary: null,
    active: null,
    countries: [],
    pages: [],
    generatedAt: null,
  });

  useEffect(() => {
    let cancelled = false;

    (async () => {
      try {
        const data = await fetchAllStats();
        if (cancelled) return;
        setState({
          loading: false,
          error: null,
          summary: data.summary,
          active: data.active,
          countries: data.countries,
          pages: data.pages,
          generatedAt: data.generatedAt,
        });
      } catch {
        if (cancelled) return;
        setState({
          loading: false,
          error: "fetch_failed",
          summary: null,
          active: null,
          countries: [],
          pages: [],
          generatedAt: null,
        });
      }
    })();

    return () => {
      cancelled = true;
    };
  }, []);

  return state;
}
